MultiLanguageSpellData['it'][88909] = {name = "[q0]Fischietto in Legno", additional_info = "2 s di lancio 5\n[q]Si tratta di un piccolo fischietto intagliato in legno di quercia. Forse veniva usato per richiamare un famiglio o una cavalcatura, o forse era solo il giocattolo di un bambino. Sembra essere stato masticato da un animale o da un giovane Nano.\n[q0]Fischietto in Legno\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][88910] = {name = "[q0]Fibbia con Insegna di Forgiamara", additional_info = "2 s di lancio 5\n[q]Modimus Forgiamara era il gran sovrano dei Nani prima della Guerra dei Tre Martelli. È lui quello rappresentato nella grande statua alle porte di Forgiardente. Questa fibbia in ottone forse apparteneva a un membro del suo corpo di guardia o a un servo.\n[q0]Fibbia con Insegna di Forgiamara\nSi vincola alla raccolta"}
