MultiLanguageSpellData['it'][89890] = {name = "[q0]Idolo Inquietante dei Bruciaspina", additional_info = "2 s di lancio 5\n[q]Quando gli Alti Elfi andarono in guerra contro i Troll Amani non riuscivano a capire come mai gli incantesimi sulle armi dei Troll fossero tanto più potenti dei loro. Gli Elfi quindi rubarono l'antica conoscenza degli incantatori Troll, tra cui il famoso Zanza, e utilizzarono idoli come questo per creare le proprie versioni degli incantamenti Troll.\n[q0]Idolo Inquietante dei Bruciaspina\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][89891] = {name = "[q0]Bijou di Cinabro", additional_info = "2 s di lancio 5\n[q]Questo piccolo bijou è formato da un minerale rosso vulcanico e tossico. L'iscrizione sul retro afferma che una volta era di proprietà di Min'loth il Serpente. Tracce di conchiglie suggeriscono che il bijou è rimasto per diverso tempo sott'acqua.\n[q0]Bijou di Cinabro\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][89892] = {name = "Lancio Bomba", additional_info = "[q0][Item Effect]Portata di 15 m\nIstantaneo\n[q]Lancia una bomba contro un vicino Pozzo di Petrolio per incendiarlo."}
MultiLanguageSpellData['it'][89893] = {name = "[q0]Moneta di Eldre'Thalas", additional_info = "2 s di lancio 5\n[q]Una volta capitale degli Alti Nobili, la città degli arcanisti della Regina Azshara cadde in rovina in seguito alla Grande Separazione. Le rovine sono ora conosciute come Maglio Infausto.\n[q0]Moneta di Eldre'Thalas\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][89894] = {name = "[q0]Falcione Infranto", additional_info = "2 s di lancio 5\n[q]Questo è un frammento di un grande proiettile a tre lame sparato da un'arma da assedio elfica. Mentre i lancialame sono comuni anche oggi, questo frammento è antico e reca decorazioni molto dettagliate anche per gli standard elfici.\n[q0]Trilama Infranto\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][89895] = {name = "[q0]Conchiglia a Spirale di Ammonite", additional_info = "2 s di lancio 5\n[q]Le ammoniti sono simili a dei calamari col guscio, ormai estinte. Il guscio poteva essere lungo come una lancia o a spirale in una varietà di forme diverse. Questo fossile è di un campione piccolo, ma ce n'erano di molto grandi.\n[q0]Conchiglia a Spirale di Ammonite\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][89896] = {name = "[q0]Anello Drago Verde", additional_info = "2 s di lancio 5\n[q]Questa è probabilmente una rappresentazione di Eranikus, consorte di Ysera. Eranikus si perse nella corruzione dell'Incubo di Smeraldo e in seguito fu redento. All'interno dell'anello leggi la scritta: \"Andu-falah-dor!\".\n[q0]Anello Drago Verde\nSi vincola alla raccolta"}
