MultiLanguageSpellData['it'][90410] = {name = "[q0]Spada Rovinata di Tunadil il Redentore", additional_info = "2 s di lancio 5\n[q]Questa lama si ruppe quando vi cadde sopra il Paladino che stava combattendo contro il dragone Kaldrigos.\n[q0]Spada Rovinata di Tunadil il Redentore\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90411] = {name = "[q0]Battente Eccentrico", additional_info = "2 s di lancio 5\n[q]Puoi solo immaginare quale fosse il tipo di residenza o di negozio che questo manufatto una volta adornava. Questo... ehm... battente ha la forma di una Nana formosa, con un sorriso sdentato, che porta allegramente diversi boccali di birra.\n[q0]Battente Eccentrico\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90412] = {name = "[q0]Tacco di Stivale Intarsiato", additional_info = "2 s di lancio 5\n[q]L'attenzione ai dettagli riservata a questo semplice tacco di stivale suggerisce che forse si trattava di calzature magiche. La decorazione è in gran parte astratta, ma è possibile scorgere immagini di piccoli animali del bosco, come scoiattoli e cervi e forse anche una puzzola, nascosti tra gli intarsi stilizzati e i nodi.\n[q0]Tacco di Stivale Intarsiato\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90413] = {name = "[q0]Vaso da Notte Dorato", additional_info = "2 s di lancio 5\n[q]A quanto pare i ricchi e i famosi fanno tutto quello che devono con stile. Questo pezzo è decorato con pesci che saltano e un ruscello.\n[q0]Vaso da Notte Dorato\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90414] = {name = "Sparizione Evocazioni", additional_info = nil}
MultiLanguageSpellData['it'][90415] = {name = "[q0]Elmo Alato di Cormartello", additional_info = "2 s di lancio 5\n[q]A giudicare dalle dimensioni di questo elmo, il Thane Cormartello dei Ferroscuro doveva essere enorme, o forse solo enormemente grasso.\n[q0]Elmo Alato di Cormartello\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90416] = {name = "Espelli Tutti i Passeggeri", additional_info = nil}
MultiLanguageSpellData['it'][90417] = {name = "Avvelena Scorte di Grano", additional_info = "[q0][Item Effect]Portata di 5 m\n1 s di lancio\n[q]Avvelena le Scorte di Grano nei Sotterranei di Roccianera."}
MultiLanguageSpellData['it'][90418] = {name = "Visuale Vulcanica", additional_info = nil}
MultiLanguageSpellData['it'][90419] = {name = "[q0]Scudo Pietrificato degli Stellaferrea", additional_info = "2 s di lancio 5\n[q]Secondo la leggenda, Thane Stellaferrea dei Nani Ferroscuro scavò questo scudo da un albero sacro degli Alti Elfi e poi incantò l'oggetto facendolo diventare duro come la pietra.\n[q0]Scudo Pietrificato degli Stellaferrea\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90420] = {name = "[q0]Fioriera a Forma di Teschio", additional_info = "2 s di lancio 5\n[q]I Troll delle Foreste hanno una grande affinità con la vita vegetale. I corpi dei Troll stessi possono essere ricoperti di vegetazione, come muschio o alghe, che dona loro il caratteristico colore verde.\n[q0]Fioriera a Forma di Teschio\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90421] = {name = "[q0]Braccialetto in Giada e Monete", additional_info = "2 s di lancio 5\n[q]Questo braccialetto è stato creato unendo monete di Troll e pezzi di giada lucidata con una catenina d'argento. Dal momento che i Troll preferiscono gioielli d'oro, è possibile che l'argento sia stato rubato a un'altra razza, cosa che renderebbe questo manufatto d'origine più recente. Le insolite monete raffigurano il volto ghignante di femmine Troll.\n[q0]Braccialetto in Giada e Monete\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90422] = {name = "Fendente Colossale", additional_info = nil}
MultiLanguageSpellData['it'][90423] = {name = "[q0]Statuetta di Gahz'rilla", additional_info = "2 s di lancio 5\n[q]I Troll della sabbia evocarono questa enorme idra bianca da una piscina sacra all'interno di Zul'farrak e poi la venerarono come divinità. Le scaglie di Gahz'rilla sono elettrificate e anche questa figurina sembra viva d'energia. All'interno di Zul'farrak, l'idra leggendaria è un motivo comune nell'architettura e nella decorazione.\n[q0]Statuetta di Gahz'rilla\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90424] = {name = "Invisibilità Transizione Glubtok", additional_info = nil}
MultiLanguageSpellData['it'][90425] = {name = "Pioggia di Fuoco", additional_info = "Portata illimitata\nIstantaneo\n[q]Infligge danni da fuoco ai nemici nell'area d'effetto."}
MultiLanguageSpellData['it'][90426] = {name = "Pioggia di Fuoco", additional_info = "Portata illimitata\nIstantaneo\n[q]Lancia una palla di fuoco nel Crogiolo della Carneficina."}
MultiLanguageSpellData['it'][90427] = {name = "Trasportato da Cromush", additional_info = nil}
MultiLanguageSpellData['it'][90428] = {name = "Lancio Inverso Cavalcabile", additional_info = nil}
MultiLanguageSpellData['it'][90429] = {name = "[q0]Scettro degli Atal'ai", additional_info = "2 s di lancio 5\n[q]Atal'ai significa \"i devoti\" in Zandali. Questo gruppo di Troll era devoto al Dio del Sangue, Hakkar: un essere di estrema malvagità che recentemente ha assaggiato il sapore amaro della sconfitta a Zul'gurub, antica capitale dell'Impero dei Gurubashi. Lo scettro è decorato con un motivo a pipistrello, forse un riferimento a Hir'eek, il dio pipistrello primordiale.\n[q0]Scettro degli Atal'ai\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90430] = {name = "Uccisione", additional_info = nil}
MultiLanguageSpellData['it'][90431] = {name = "Individua Invisibilità Missione 7", additional_info = nil}
MultiLanguageSpellData['it'][90432] = {name = "[q0]Dente di Gigantosauro", additional_info = "2 s di lancio 5\n[q]I gigantosauri sono tra i predatori più grandi mai apparsi su Azeroth. Mentre la maggior parte di loro è scomparsa secoli fa, alcuni sono sopravvissuti fino ad oggi in zone isolate. Ci sono diverse teorie sull'utilità delle loro piccole zampe anteriori: alcuni sostengono che aiutino i gigantosauri a rialzarsi, altri che servano ad attirare le femmine. Sono necessari ulteriori studi.\n[q0]Dente di Gigantosauro\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90433] = {name = "[q0]Insetto nell'Ambra", additional_info = "2 s di lancio 5\n[q]L'ambra è la resina degli alberi pietrificata. Uno degli scopi della resina degli alberi è difendere l'albero dall'attacco degli insetti, quindi alcune gocce di ambra particolarmente rare possono contenere insetti perfettamente conservati.\n[q0]Insetto nell'Ambra\nSi vincola alla raccolta"}
