MultiLanguageSpellData['it'][90451] = {name = "[q0]Anfora dei Kaldorei", additional_info = "2 s di lancio 5\n[q]Questo vaso slanciato con due manici a voluta è stato utilizzato per mescolare o conservare del vino darnassiano. Ancora, dopo tutto questo tempo, è possibile sentire un vago profumo di zenzero dal residuo secco rimasto sul fondo.\n[q0]Anfora dei Kaldorei\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90452] = {name = "[q0]Fauci di Squalo Antico", additional_info = "2 s di lancio 5\n[q]Gli squali non hanno vere e proprie ossa, ma cartilagini. Non è raro che perdano i denti, perché le loro abitudini alimentari prevedono morsi dati con grande decisione. Per questo gli squali sono dotati di più file di denti, che vengono sostituiti di continuo nel corso della loro vita.\n[q0]Fauci di Squalo Antico\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90453] = {name = "[q0]Forcina in Argento e Malachite", additional_info = "2 s di lancio 5\n[q]Incise sotto il castone della pietra preziosa ci sono le parole: \"A Theleste, per il suo ventiquattresimo compleanno\".\n[q0]Forcina in Argento e Malachite\nSi vincola alla raccolta"}
