MultiLanguageSpellData['it'][90458] = {name = "[q0]Carillon Delicato", additional_info = "2 s di lancio 5\n[q]Questa scatola in legno di sandalo ha un piccolo orologio all'interno, con un'Elfa e una Fiera della Notte. Sebbene il meccanismo non funzioni più, puoi immaginare i due ballare insieme con la musica in sottofondo. Incisa sul fondo c'è la scritta: \"Alla mia adorata Theleste\".\n[q0]Carillon Delicato\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90459] = {name = "Item - Death Knight T11 DPS 4P Bonus", additional_info = "[q]Ottenere una runa della morte o attivare Arma Letale aumenta del 1% la potenza d'attacco per 30 s. Si accumula fino a 3 volte."}
