MultiLanguageSpellData['it'][90518] = {name = "[q0]Catena in Mithril dei Forgiarabbia", additional_info = "2 s di lancio 5\n[q]La famiglia Forgiarabbia ha una lunga tradizione nella storia dei Nani Ferroscuro. Questa è la catena indossata dal Thane dei Forgiarabbia, l'antenato del Generale Forgiarabbia, che ancora comanda l'esercito dei Ferroscuro nei Sotterranei di Roccianera.\n[q0]Catena in Mithril dei Forgiarabbia\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90519] = {name = "[q0]Bastone con Teschio di Forgiascura", additional_info = "2 s di lancio 5\n[q]La famiglia Forgiascura ha lasciato una grossa macchia nella storia dei Ferroscuro. Il Thane di Ferro Forgiadombra è stato a detta di tutti un despota crudele che ha torturato e ucciso molti dei suoi stessi sudditi. Generalmente si pensa che fosse uno Stregone, ma voci dicono che lui fu il primo dei Nani Sciamani.\n[q0]Bastone con Teschio di Forgiascura\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90520] = {name = "Sovraccarico Arcano", additional_info = nil}
MultiLanguageSpellData['it'][90521] = {name = "[q3]Gnomo Meccanico", additional_info = "2 s di lancio 15\n[q]I Meccanognomi furono creati dai Titani, apparentemente come servitori e custodi, proprio come i terrigeni. Questo Meccanognomo dev'essere danneggiato, perché non è più concentrato sui suoi compiti originali ma sembra contento di seguirti.\n[q3]Gnomo Meccanico\nSi vincola alla raccolta\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare uno Gnomo Meccanico.\nRichiede dal livello 1 al 80 ( 80)"}
