MultiLanguageSpellData['it'][90831] = {name = "[q0]Frusta Demoniaca", additional_info = "2 s di lancio 5\n[q]Gli Stregoni sono saliti alla ribalta tra gli Orchi quando Gul'dan è salito al potere. Questa frusta è formata dalle carni intrecciate di diverse creature, alcune delle quali probabilmente umanoidi.\n[q0]Frusta Demoniaca\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90832] = {name = "[q0]Piastrella in Creta Lucida", additional_info = "2 s di lancio 5\n[q]Dev'esserci stato un tempo in cui molte di queste piastrelle decoravano i muri o i pavimenti delle fortezza di Draenor. La piastrella raffigura un gregge di animali su un campo smaltato in verde e giallo, molto simile a com'è Nagrand oggi. Il bordo è una scacchiera nera e marrone.\n[q0]Piastrella in Creta Lucida\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90833] = {name = "[q0]Teschio per Libagioni", additional_info = "2 s di lancio 5\n[q]Questa \"coppa\" ha un aspetto feroce, ma ha un difetto: il liquido fuoriesce dai buchi delle orbite. Che sete...\n[q0]Teschio per Libagioni\nSi vincola alla raccolta"}
