MultiLanguageSpellData['it'][90860] = {name = "[q0]Arpa Intarsiata in Legno Esotico", additional_info = "2 s di lancio 5\n[q]Questa piccola arpa veniva tenuta in una mano, come una lira. Ha una cassa di risonanza in legno con sette corde annodate attorno ad una barra per l'accordatura. Potrebbe riprodurre musica, ma sembra che suoni solo note tristi e malinconiche.\n[q0]Arpa Intarsiata in Legno Esotico\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90861] = {name = "[q0]Strano Fermacarte in Argento", additional_info = "2 s di lancio 5\n[q]Se questo oggetto non è un fermacarte Draenei, allora non hai davvero idea di che cosa sia. Sembra una goccia di mercurio pietrificato con un lato piatto in modo da poter stare fermo su una scrivania.\n[q0]Strano Fermacarte in Argento\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90864] = {name = "[q0]Scettro del Nathrezim", additional_info = "2 s di lancio 5\n[q]I Nathrezim, noti anche come Signori del Terrore, furono agenti e investigatori della Legione Infuocata. Anche se sono potenti nemici sul campo di battaglia, preferiscono mettere i popoli l'uno contro l'altro manipolandoli astutamente.\n[q0]Scettro del Nathrezim\nSi vincola alla raccolta"}
