MultiLanguageSpellData['it'][90950] = {name = "Fiamme Divoratrici", additional_info = "Portata illimitata\n2.5 s di lancio\n[q]Le Fiamme Divoratrici infliggono 11344653 danni da ombra ogni 1 s. I danni si riducono all'aumentare della distanza del bersaglio dal punto di origine delle Fiamme Divoratrici."}
