MultiLanguageSpellData['it'][90971] = {name = "Assorbimento Spirito", additional_info = nil}
MultiLanguageSpellData['it'][90974] = {name = "[q0]Candelabro in Cristallo Pregiato", additional_info = "2 s di lancio 5\n[q]Questo candelabro un tempo reggeva una decina di candele. Cristalli blu e viola collegati da catene sottili e intarsi ornamentali pendono dai suoi bracci. Sul fondo sono incise le iniziali dell'artigiano che l'ha creato: \"V.T.\".\n[q0]Candelabro in Cristallo Pregiato\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90975] = {name = "[q0]Ritratto Nobiliare", additional_info = "2 s di lancio 5\n[q]Si tratta di un dipinto a olio raffigurante un Draenei nobile e serio. Mentre l'opera nel suo complesso ha un intento adulatorio, capisci chiaramente che l'artista ha preso in giro il suo soggetto: appena sopra la cornice, nella parte inferiore del dipinto, vedi che il nobile è stato ritratto senza pantaloni.\n[q0]Ritratto Nobiliare\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90976] = {name = "Richiamo della Banshee", additional_info = "[q0][Item Effect]Portata di 45 m\nIstantaneo\n[q]Richiama una Banshee che recuperi un Agente dell'IR:7 ferito. Il bersaglio dev'essere al di sotto del 35% di salute restante."}
MultiLanguageSpellData['it'][90977] = {name = "Evocazione: Medium", additional_info = nil}
MultiLanguageSpellData['it'][90978] = {name = "Energizza!", additional_info = "3 s di lancio\n[q]Aumenta la velocità d'attacco e di lancio d'incantesimi del 50% e i danni inflitti del 25%."}
MultiLanguageSpellData['it'][90980] = {name = "Fendente", additional_info = "{Portata di mischi}a}\nProssimo Mano a Mano\n[q]Infligge il 150% dei danni in mischia normali a un nemico e ai suoi alleati più vicini, colpendo fino a un massimo di 3 bersagli."}
MultiLanguageSpellData['it'][90983] = {name = "[q3]Arrivo dei Naaru", additional_info = "2 s di lancio 15\n[q]Questo cristallo sembra essere un dispositivo di registrazione magica. Il messaggio che viene riprodotto è in una lingua che non conosci, ma intuisci che potrebbe essere la registrazione o la riproduzione del primo incontro tra gli Eredar e i Naaru.\n[q3]Arrivo dei Naaru\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Osservi una testimonianza visiva dell'arrivo dei Naaru. (3 Min Recupero)"}
MultiLanguageSpellData['it'][90984] = {name = "[q3]Ultima Reliquia di Argus", additional_info = "2 s di lancio 15\n[q]Prima di abitare su Azeroth o Draenor, i Draenei, che ai tempi si chiamavano Eredar, vivevano su Argus. Quando Sargeras si accorse di Argus, il Profeta Velen dovette fuggire con parte del suo popolo, e da allora divennero Draenei. Gli Eredar che restarono divennero parte della Legione Infuocata. Velen prese questo semplice cristallo quando fuggì. L'iscrizione sul fondo dice: \"'Sogno la città di Eredath\".\n[q3]Ultima Reliquia di Argus\nSi vincola alla raccolta\n[q2]Usa: Ti teletrasporta esattamente dove tu vuoi... Se non sei troppo esigente. (12 Ore Recupero)\n[q]\"Una delle poche cose che i Draenei riuscirono a portare con sé nel viaggio da Argus.\""}
MultiLanguageSpellData['it'][90985] = {name = "Venti Contrari", additional_info = "Venti Contrari Livello 80\nIstantaneo\n[q]Aumenta l'Intelletto di 2 per 15 s."}
MultiLanguageSpellData['it'][90986] = {name = "Venti Contrari", additional_info = "Venti Contrari Livello 80\n[q0][Item Effect][q]Gli incantesimi periodici d'attacco e di cura forniscono 2 Intelletto ogni volta che infliggono danni o curano. Dura 15 s. Si accumula fino a 20 volte.\n(500ms di recupero)"}
MultiLanguageSpellData['it'][90987] = {name = "[q0]Pungolo Placcato per Elekk", additional_info = "2 s di lancio 5\n[q]Gli Elekk sono creature native di Draenor, in particolare della regione di Nagrand, simili ai mammut. I Draenei addomesticarono gli Elekk per usarli come cavalcatura. Questo pungolo è un lungo bastone usato per comandare gli Elekk non del tutto domati.\n[q0]Pungolo Placcato per Elekk\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][90988] = {name = "[q0]Chiave Elaborata per Scrigno", additional_info = "2 s di lancio 5\n[q]Anche se la tecnologia Vrykul in generale è meno complessa di quella dell'Orda o dell'Alleanza, il dettaglio del disegno su questa semplice chiave è stupefacente. Nella cultura Vrykul di solito è la donna della famiglia che tiene tutte le chiavi, spesso ben visibili per mostrare il suo status. \"Non apre la Cassa di Salem il Chierico Oscuro\".\n[q0]Chiave Elaborata per Scrigno\nSi vincola alla raccolta"}
