MultiLanguageSpellData['it'][91008] = {name = "[q0]Scramasax", additional_info = "2 s di lancio 5\n[q]Gli Scramasax sono grandi coltelli dritti con un solo bordo tagliente e un'impugnatura semplice utilizzati da molti guerrieri Vrykul come arma aggiuntiva. Uno stile di lotta comune tra i guerrieri prevede infatti un'ascia nella mano primaria e uno Scramasax in quella secondaria.\n[q0]Scramasax\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91009] = {name = "Forza del Rinnegato", additional_info = "Istantaneo\n[q]Infonde il bersaglio di forza dei Defias. Aumenta i danni fisici inflitti del 200%, riduce i danni subiti da incantesimi e abilità ad area d'effetto del 90% e aumenta la salute del 300%."}
