MultiLanguageSpellData['it'][91209] = {name = "[q0]Brocca di Sangue di Jormungar", additional_info = "2 s di lancio 5\n[q]Una bottiglia di vetro contenente il sangue acido e gelido di uno dei vermi jormungar di Nordania. Secondo la leggenda, i Nerubiani usarono i jormungar per scavare molti dei passaggi sotterranei e delle grotte che costituivano le grandi città di Azjol-Nerub.\n[q0]Brocca di Sangue di Jormungar\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91211] = {name = "[q0]Stendardo Grezzo del Visir", additional_info = "2 s di lancio 5\n[q]Questo strano oggetto sembra essere un frammento di una grandissima pergamena. Il materiale è un incrocio tra il papiro e il cuoio, ed è coperto di diagrammi e scritte in Nerubiano in rosso e cremisi. \"Unhhh-tikk-a-shisss. Kka shir. Na-l bkah a-shisss. Kreesh kik ik ta. Sohk-a tik hiss a-k-k-k\".\n[q0]Stendardo Grezzo del Visir\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91212] = {name = "Impeto Improvviso", additional_info = "Portata di 45 m\n{Istantaneo} {3 s di recupero}\n[q]Carica un nemico, infliggendo 14 danni al bersaglio e agli alleati vicini respingendoli indietro."}
MultiLanguageSpellData['it'][91213] = {name = "Frantumazione", additional_info = "Istantaneo\n[q]Infligge 1312 danni fisici ai bersagli nemici entro 10 m."}
MultiLanguageSpellData['it'][91214] = {name = "[q4]Benedizione del Dio Antico", additional_info = "2 s di lancio 15\n[q]Pwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal. Pwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal. Pwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal.\n[q4]Benedizione del Dio Antico\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Ricevi la Benedizione di un Dio Antico per 20 s. (10 Min Recupero)"}
MultiLanguageSpellData['it'][91215] = {name = "[q4]Scatola Rompicapo di Yogg-Saron", additional_info = "2 s di lancio 15\n[q]Questa scatolina ha diversi pannelli semovibili, cerniere di collegamento e fermagli nascosti. Ma nonostante i tuoi tentativi, aprirla e rivelarne il contenuto sembra impossibile. È difficile anche solo provarci perché quest'oscuro manufatto continua a bisbigliare: \"È stata colpa TUA, è stata colpa TUA, è stata colpa TUA.\".\n[q4]Scatola Rompicapo di Yogg-Saron\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Un vano tentativo di aprire la scatola a incastro. (1 Min Recupero)\n[q]\"Estremamente difficile da aprire.\""}
