MultiLanguageSpellData['it'][91218] = {name = "Visuale Fantasma", additional_info = nil}
MultiLanguageSpellData['it'][91219] = {name = "[q0]Kris Argenteo di Korl", additional_info = "2 s di lancio 5\n[q]È inciso con il sangue del cuore morente del dragone Kaldrigos.\n[q0]Kris Argenteo di Korl\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91220] = {name = "Ruggito Tremante", additional_info = "1 s di lancio\n[q]Un ruggito da brividi, che spaventa tutti i nemici vicini per 3 s. Eventuali danni inflitti al bersaglio interrompono l'effetto."}
MultiLanguageSpellData['it'][91221] = {name = "[q0]Maglio da Guerra di Occhioardente", additional_info = "2 s di lancio 5\n[q]Il Thane di Ferro Occhioardente si divertiva in battaglia. Era famoso per l'abilità con cui maneggiava una coppia di enormi magli da guerra. Ne hai ricostruito uno, ormai svuotato dalla magia. Ciò significa che l'altro potrebbe essere là fuori da qualche parte e forse è ancora un'arma potente.\n[q0]Maglio da Guerra di Occhioardente\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91222] = {name = "Scuotimento", additional_info = nil}
MultiLanguageSpellData['it'][91223] = {name = "[q0]Guanti Chiodati di Forgiafuria", additional_info = "2 s di lancio 5\n[q]Forgiafuria fu uno dei più potenti generali dei Sotterranei di Roccianera. Il suo simbolo, un'incudine fiammeggiante, è visibile ancora oggi sulle insegne e sugli scudi a Roccianera. Anche se non comanda più l'esercito dei Ferroscuro, molti soldati portano ancora il suo nome.\n[q0]Guanti Chiodati di Forgiafuria\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91224] = {name = "[q0]Verbo dell'Imperatrice Zoe", additional_info = "2 s di lancio 5\n[q]Il Verbo e il Giuramento dell'Imperatrice Zoe una volta erano una coppia di potenti anelli magici. L'anello che hai recuperato era il Verbo, ma purtroppo ha perso le sue proprietà magiche quando è andato in frantumi. Il Giuramento si è perso ma forse è ancora magico. La stessa Imperatrice era una sovrana dei Ferroscuro poco nota. Molti Nani hanno perso la vita a causa della sua ossessione per i draghi e dei suoi tentativi di rubare le loro uova o i loro piccoli.\n[q0]Verbo dell'Imperatrice Zoe\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91225] = {name = "[q0]Scettro di Barbabronzea", additional_info = "2 s di lancio 5\n[q]Barbabronzea è sia il nome di un clan di Nani, sia il cognome della famiglia regnante. I re della Sala del Trono hanno cambiato spesso scettro durante i loro regni. Per tradizione, il re lasciava il suo scettro ad alcuni dei suoi consiglieri e alleati per un giorno. Erano giorni pesanti per gli scettri, che visitavano le taverne, cadevano dalla cima delle montagne, venivano picchiati sulla testa dei Trogg e così via.\n[q0]Scettro di Barbabronzea\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91226] = {name = "[q3]Figlia del Locandiere", additional_info = "2 s di lancio 15\n[q]Secondo la leggenda, Bryher Guardiapietra gestiva una locanda vicino a Loch Modan. Sua figlia Keelin amava allontanarsi da casa, guadagnando alla fine quel tipo di reputazione che imbarazza un padre. Bryher chiese a uno Gnomo Stregone di far sì che sua figlia restasse vicina a casa. Lo Stregone allora trasformò Keelin in una Pietra del Ritorno, così sarebbe sempre tornata alla locanda.\n[q3]Figlia del Locandiere\nSi vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Ti riporta a \"[Hearthstone Location]\". Parla con un locandiere in un luogo differente per cambiare la tua dimora."}
MultiLanguageSpellData['it'][91227] = {name = "[q4]Bastone del Thane Occultista Thaurissan", additional_info = "2 s di lancio 15\n[q]Il Thane Occultista Thaurissan fu il capo dei Nani Ferroscuro durante la Guerra dei Tre Martelli. Quando perdette Forgiardente a favore del Clan Barbabronzea, Thaurissan si ritirò nelle Montagne Crestarossa e fondò una città col suo nome. In un disperato tentativo di sconfiggere i nemici, Thaurissan evocò per errore il semidio Ragnaros: l'Occultista Thane morì immediatamente e si formò il picco vulcanico del Massiccio Roccianera.\n[q4]Bastone del Thane Occultista Thaurissan\n[q7]Si vincola alla Brigata\nDue mani Bastone\n4 - 6 Danni Velocità 3.60\n(1.4 danni per secondo)\n+18 Intelletto\n+6 Tempra\n[q2]+ 4 Critico\n[q2]+ 4 Celerità\nIntegrità 120 / 120\n32"}
