MultiLanguageSpellData['it'][91757] = {name = "[q4]Bambola Preferita di Tyrande", additional_info = "2 s di lancio 15\n[q]Tyrande Soffiabrezza è la Gran Sacerdotessa di Elune, e dopo il suo recente matrimonio non è più la sola a regnare sugli Elfi della Notte. È cresciuta nell'antica città di Suramar, lontano dal primo Pozzo dell'Eternità, ma vicina ai fratelli Malfurion e Illidan Grantempesta. L'infanzia idilliaca di Tyrande si è rivelata in netto contrasto con il dolore e il conflitto che avrebbe poi dovuto sopportare nella sua vita.\n[q4]Bambola Preferita di Tyrande\n[q7]Si vincola alla Brigata\nUnico equipaggiabileMonile\n+4 Intelletto\n[q2]Equipaggia: Recuperi il 20% del costo base in mana degli incantesimi, accumulandolo nella bambola per un utilizzo futuro. Puoi accumulare un massimo di 50 mana.\n[q2]Usa: Rilascia il mana contenuto nella bambola, fornendoti tale ammontare di mana e infliggendo la metà del mana rilasciato in danni da arcano ai nemici entro 0 m. (1 Min Recupero)\n32"}
MultiLanguageSpellData['it'][91758] = {name = "Camuffamento Bengala di Segnalazione", additional_info = nil}
MultiLanguageSpellData['it'][91759] = {name = "Esplosione del Trinciacieli", additional_info = nil}
MultiLanguageSpellData['it'][91760] = {name = "Trasformazione Naga", additional_info = "[q0][Item Effect]Istantaneo\n[q]Ti trasformi in un Naga per 2 min."}
MultiLanguageSpellData['it'][91761] = {name = "[q4]Ossa della Trasformazione", additional_info = "2 s di lancio 15\n[q]Quando il primo pozzo dell'Eternità implose, fece affondare il centro della cultura Kaldorei sul fondo del mare. Per sfuggire a morte certa, la Regina Azshara fece un patto con un potere superiore, forse un Dio Antico o un elementale, causando la discesa di una maledizione sugli Alti Nobili sopravvissuti, che divennero creature simili a serpenti, una razza ora conosciuta come Naga.\n[q4]Ossa della Trasformazione\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Ti trasformi in un Naga per 2 min. (10 Min Recupero)"}
MultiLanguageSpellData['it'][91762] = {name = "[q0]Pendente dei Cento Magi", additional_info = "2 s di lancio 5\n[q]Durante le guerre dei Troll, gli Elfi di Quel'Thalas furono quasi sconfitti dai Troll Amani. Disperati, gli Elfi insegnarono agli Umani di Arathor le arti della magia arcana. Solo cento uomini ebbero accesso a quest'arte magica, il minimo indispensabile per sconfiggere i Troll. Gli Umani si rivelarono incantatori goffi ma con una naturale affinità per la magia.\n[q0]Pendente dei Cento Magi\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91763] = {name = "Accetta incantesimi", additional_info = nil}
MultiLanguageSpellData['it'][91764] = {name = "Individua Invisibilità 11", additional_info = nil}
MultiLanguageSpellData['it'][91765] = {name = "Individua Invisibilità 12", additional_info = nil}
MultiLanguageSpellData['it'][91766] = {name = "[q0]Portapergamene in Argento", additional_info = "2 s di lancio 5\n[q]Questo portapergamene elfico è abbellito con molte decorazioni, ma è il messaggio all'interno, scritto in darnassiano, a essere particolarmente interessante: \"Pyramond, non devi assolutamente passare del tempo con quella donna alla taverna. Tua madre e io te lo vietiamo. Lei è molto al di sotto del tuo livello.\"\n[q0]Portapergamene in Argento\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91767] = {name = "Individua Invisibilità 13", additional_info = nil}
MultiLanguageSpellData['it'][91768] = {name = "Evocazione: Agatha", additional_info = nil}
MultiLanguageSpellData['it'][91769] = {name = "[q0]Ombra Crescente", additional_info = "2 s di lancio 5\n[q]Si tratta di una lama circolare molto apprezzata dai Guardiani degli Elfi della Notte. Questo tipo di arma è famosa per essere stata brandita da Maiev Cantombroso, ma viene usata ancora oggi dai Guardiani delle Profondità dell'Eremo al Monte Hyjal. Probabilmente l'arma che hai recuperato era anche magica, prima di spezzarsi in tanti frammenti.\n[q0]Ombra Crescente\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91770] = {name = "Bengala di Segnalazione 01", additional_info = nil}
MultiLanguageSpellData['it'][91771] = {name = "Forma di Fuoco Fatuo", additional_info = "[q0][Item Effect]Istantaneo\n[q]Assumi la Forma di Fuoco Fatuo per 2 min."}
MultiLanguageSpellData['it'][91773] = {name = "[q4]Amuleto del Fuoco Fatuo", additional_info = "2 s di lancio 15\n[q]I Fuochi Fatui sono spiriti della natura che si pensa siano Elfi della Notte defunti. Vivono in stretta connessione con la loro foresta d'origine e gli Elfi della Notte in generale: Per difendere la comunità degli Elfi della Notte fanno anche azioni come costruire o riparare. Molti Fuochi Fatui si sono sacrificati per sconfiggere Archimonde alla fine della Terza Guerra, quindi oggi ci sono meno Fuochi Fatui di un tempo.\n[q4]Amuleto del Fuoco Fatuo\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Assumi la Forma di Fuoco Fatuo per 2 min. (10 Min Recupero)"}
MultiLanguageSpellData['it'][91774] = {name = "Uccisione Bengala di Segnalazione 01", additional_info = nil}
MultiLanguageSpellData['it'][91775] = {name = "[q0]Castello di Sabbia", additional_info = "2 s di lancio 5\n[q]È una piccola fortezza quadrata fatta di sabbia. Le torri e il motivo del sole suggeriscono si tratti di architettura Tol'vir, ma non hai mai visto nulla di simile in tutta Uldum. L'oggetto è chiaramente fatto di sabbia, non di arenaria, quindi non hai idea di come possa stare insieme.\n[q0]Castello di Sabbia\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91776] = {name = "Sfregio", additional_info = "{40 energia} Portata di mis{chia}\nIstantaneo\n[q]Graffia il nemico, infliggendo [0.54 * ([Attack Power] * 0.3) * (1 + Versatilità) * 1 ] danni fisici."}
MultiLanguageSpellData['it'][91777] = {name = "Aura Guardiano di Tirisfal", additional_info = nil}
MultiLanguageSpellData['it'][91778] = {name = "Spazzata d'Artigli", additional_info = "{40 energia} Portata di mis{chia}\nIstantaneo\n[q]Graffia il nemico con artigli deformi, infliggendo [0.54 * ([Attack Power] * 0.15) * (1 + Versatilità) * 3 * 1 ] danni da ombra al bersaglio e ai nemici vicini."}
MultiLanguageSpellData['it'][91779] = {name = "[q0]Statua di Gatto con Occhi di Smeraldo", additional_info = "2 s di lancio 5\n[q]Questo gatto di terracotta ha una posa e un'espressione realistiche. La parte inferiore reca un'incisione: \"In memoria di Chalyx, animale prediletto dell'Imperatore Ninjter\".\n[q0]Statua di Gatto con Occhi di Smeraldo\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91780] = {name = "[q0]Collana di Scarabeo in Steatite", additional_info = "2 s di lancio 5\n[q]\"Regalato all'imperatore Ninjter il giorno in cui salì al trono. Ci aspettiamo grandi cose dal suo regno.\"\n[q0]Collana di Scarabeo in Steatite\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91781] = {name = "Bengala di Segnalazione 02", additional_info = nil}
MultiLanguageSpellData['it'][91782] = {name = "[q0]Piccolo Mosaico di Oasi", additional_info = "2 s di lancio 5\n[q]Questo piccolo capolavoro artistico è stato creato usando frammenti di laterizi colorati, verdi e turchesi, e sabbia. \"Le nostre speranze e preghiere sono per l'imperatore Ninjter, che egli possa porre fine alla carestia e rigenerare la gloria dei Ramkahen!\"\n[q0]Piccolo Mosaico di Oasi\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91783] = {name = "Bengala di Segnalazione 03", additional_info = nil}
MultiLanguageSpellData['it'][91784] = {name = "Uccisione Bengala di Segnalazione 02", additional_info = nil}
MultiLanguageSpellData['it'][91785] = {name = "[q0]Elsa Intarsiata di Scimitarra", additional_info = "2 s di lancio 5\n[q]Questa scimitarra sembra più una decorazione che un'arma. La lama termina dopo solo pochi centimetri, ma comunque non sembra aver visto molte battaglie. Intarsiate a spirale intorno all'impugnatura, si possono leggere le parole \"Possa l'Imperatore Ninjter portarci alla vittoria! Kadesh! Osadi! Satekh!\".\n[q0]Elsa Intarsiata di Scimitarra\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][91786] = {name = "Strangola Bersaglio", additional_info = "Portata di 25 m\nIstantaneo\n[q]Afferra un passeggero e lo porta dentro."}
MultiLanguageSpellData['it'][91787] = {name = "Piazzamento Esplosivi", additional_info = "[q0][Item Effect]1 s di lancio\n[q]Piazza gli Esplosivi di Spezzaselce nelle viscere del Trinciacieli."}
MultiLanguageSpellData['it'][91788] = {name = "Palla di Cannone", additional_info = "Portata di 70 m\n1 s di lancio\n[q]Spara una palla di cannone al nemico, infliggendo danni ingenti e stordendolo."}
MultiLanguageSpellData['it'][91790] = {name = "Vaso Canopo", additional_info = "2 s di lancio 5\n[q]Questo vaso contiene gli organi pietrificati dell'Imperatore Ninjter. A quanto pare è morto dopo solo pochi anni dall'inizio di quello che sperava sarebbe stato un lungo regno di gloria.\nSi vincola alla raccolta\n[q2]<Destra Aprire>"}
