MultiLanguageSpellData['it'][93440] = {name = "[q0]Calzini Nanici da Infante", additional_info = "2 s di lancio 5\n[q]All'inizio pensavi fossero fatti di pietra. Invece no, sono solo incrostati.\n[q0]Calzini Nanici da Infante\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][93441] = {name = "[q0]Collana con Pendente di Elune", additional_info = "2 s di lancio 5\n[q]Elune è la dea principale degli Elfi della Notte. È associata alla più grande delle due lune, la Dama Bianca. È una dea di pace, ma non pacifista. Uno dei suoi Aspetti è la Guerriera della Notte, che prende i più valorosi tra i morti e li guida attraverso il cielo come stelle.\n[q0]Collana con Pendente di Elune\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][93442] = {name = "[q0]Scheggia di Legno Pietrificato", additional_info = "2 s di lancio 5\n[q]La corteccia non si è conservata, ma si vede perfettamente la struttura vascolare del legno. Si trattava molto probabilmente di un tipo di palma.\n[q0]Scheggia di Legno Pietrificato\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][93443] = {name = "[q0]Strano Verme Vellutato", additional_info = "2 s di lancio 5\n[q]Il fossile dev'essere un anello mancante di qualche tipo. Condivide le proprietà di artropodi e vermi: ha il corpo vermiforme, ma le gambe tozze, come un insetto o un crostaceo. Sembra sia ricoperto di un sottile velluto simile a peli.\n[q0]Strano Verme Vellutato\nSi vincola alla raccolta"}
MultiLanguageSpellData['it'][93444] = {name = "[q0]Posate Raffinate degli Scalporosso", additional_info = "2 s di lancio 5\n[q]D'accordo, è solo un grosso coltello, ma in una cultura come quella della Tribù Scalporosso qualsiasi utensile di una certa utilità conta come una posata raffinata.\n[q0]Posate Raffinate degli Scalporosso\nSi vincola alla raccolta"}
