MultiLanguageSpellData['it'][113966] = {name = "Spine", additional_info = "Portata di 30 m\nIstantaneo\n[q]Delle spine fuoriescono dal bersaglio alleato, infliggendo danni da natura agli attaccanti quando colpiscono. Dura 1 min."}
MultiLanguageSpellData['it'][113967] = {name = "Frecciata d'Aculei", additional_info = "Portata di 10 m\n2 s di lancio\n[q]Lancia spine contro il nemico, infliggendo danni da natura."}
MultiLanguageSpellData['it'][113968] = {name = "Servizio da Tè dei Pandaren", additional_info = "2 s di lancio 3\n[q]Il tè è un aspetto importante della storia dei Pandaren. Grande attenzione è sempre stata data alla produzione di birra, ma saper godere di una buona tazza di tè è un segreto da molti apprezzato. Questo semplice servizio da tè è stato creato al tempo del regno dei Mogu e rappresentava quindi un momento di conforto e sollievo durante giorni di dolore e tirannia. Anche se è incrinato e spezzato, ricorda a tutti l'importanza di saper trarre consolazione dai piaceri semplici della vita."}
MultiLanguageSpellData['it'][113969] = {name = "Senza Armatura", additional_info = "Portata di 100 m\nIstantaneo\n[q]Aumenta i danni subiti del 200%."}
MultiLanguageSpellData['it'][113970] = {name = "Senza Armatura", additional_info = "Portata di 100 m\nIstantaneo\n[q]Aumenta i danni subiti del 200%."}
MultiLanguageSpellData['it'][113971] = {name = "Scacchiera dei Pandaren", additional_info = "2 s di lancio 3\n[q]Ai Pandaren piace giocare. Questo, in particolare, era il gioco preferito tra i Pandaren fin dai tempi del primo Imperatore dei Pandaren. Questa scacchiera è un fine pezzo antico."}
MultiLanguageSpellData['it'][113972] = {name = "Servizio di Boccali Gemelli del Padre della Birra Quan Tou Kuo", additional_info = "2 s di lancio 3\n[q]Un servizio completo di boccali fatti di ebano e giada. Il Padre della Birra Quan Tou Kuo, detto Doppio Pugno, ha cercato di mitigare gli effetti collaterali delle bevande forti creando una coppia perfetta di birre. Bevute insieme, nella giusta quantità, la Birra Chiara dello Spirito e la Birra Scura della Mente si combinano nello stomaco del bevitore facendogli raggiungere uno stato di illuminazione e di benessere, senza la perdita di giudizio e di autocontrollo così frequentemente causata da birre meno raffinate. Purtroppo, i segreti del Padre della Birra sono andati perduti, ma questi boccali finemente lavorati sono un ricordo imperituro del suo esperimento."}
MultiLanguageSpellData['it'][113973] = {name = "Bastone di Bambù del Padre della Birra Ren Yun", additional_info = "2 s di lancio 3\n[q]Uno dei molti bastoni, un tempo utilizzati dall'enigmatico Padre della Birra Ren Yun. Cieco dalla nascita, Ren Yun sviluppò gli altri sensi e cominciò a percepire le birre del suo tempo come troppo aspre o troppo amare. Anni di sperimentazione gli permisero di completare la ricetta di quattro birre perfette: una per ognuno dei suoi sensi. Eppure, continuava a sfuggirgli quell'unica birra che sarebbe stata la somma di tutte e quattro. Fu solo alla fine della sua lunga vita che riuscì a ottenere la ricetta perfetta, la Birra dei Quattro Sensi, la scoperta più sensazionale della sua generazione. Purtroppo la ricetta andò perduta con il passare del tempo, perché la scrittura di Ren Yun era praticamente illeggibile..."}
MultiLanguageSpellData['it'][113974] = {name = "Barile Vuoto del Padre della Birra Xin Wo Yin", additional_info = "2 s di lancio 3\n[q]Lo zipolo a forma di cuore di questa botte prova che si tratti di un manufatto dell'ultimo grande Padre della Birra Xin Wo Yin, detto Cuore Spezzato. Generazioni fa, questo famoso Padre della Birra creò la Birra Cuorfelice, capace di infondere in chi la beveva un profondo senso di calore e di benessere. Si diceva che Xin Wo Yin amasse talmente tanto questo prodotto della sua arte da piangere lacrime amare ogni volta che un barile di birra lasciava il suo birrificio. Probabilmente pianse molto anche su questo barile. E dato che è vuoto, anche a te viene un po' da piangere."}
MultiLanguageSpellData['it'][113975] = {name = "Specchio di Bronzo Lavorato", additional_info = "2 s di lancio 3\n[q]Il vetro è andato perduto, ma il retro di questo specchio è un disco finemente scolpito in bronzo raffigurante la Gru Rossa della Speranza. Un'iscrizione recita: \"Alla mia adorata Lin / Mia bellezza, mia speranza / Un'immagine di perfezione / Il tuo riflesso / Con amore - Yao\"."}
MultiLanguageSpellData['it'][113976] = {name = "Statuetta Funeraria di Porcellana Intarsiata d'Oro", additional_info = "2 s di lancio 3\n[q]Commissionate al momento della morte di una persona cara, statuette come questa aiutano a superare il dolore per la perdita. Questa statuetta raffigura un giovane Ramingo della Sapienza Pandaren di nome Lin. L'iscrizione indica che morì a causa di una terribile febbre che aveva decimato la Valle dei Quattro Venti durante il breve regno di Riggatigga, Imperatore Hozen."}
MultiLanguageSpellData['it'][113977] = {name = "Barattoli dello Speziale", additional_info = "2 s di lancio 3\n[q]Una serie completa di barattoli e vasi in ottone, con etichette ben incise, pensato per la conservazione di rare e potenti erbe medicinali. Sebbene l'uso esatto della maggior parte delle erbe rimanga un mistero, una targa sulla scatola che le contiene identifica lo speziale con Yao Zampa Sicura, un nome ancora oggi associato a salute e benessere nella Valle dei Quattro Venti grazie al suo incredibile lavoro. La leggenda vuole che Yao non si sia mai sposato perché custodiva nel cuore un dolore profondo."}
MultiLanguageSpellData['it'][113978] = {name = "Perla di Yu'lon", additional_info = "2 s di lancio 3\n[q]Tutt'intorno a questa sfera di giada, esattamente a metà, vi è inciso un serpente che si mangia la coda. Iscrizioni su entrambe le semisfere recitano: \"C'è una sola certezza, che ogni fine segna un nuovo inizio\". Questa sfera fu scolpita durante il regno di Shu Occhio Cieco, Imperatore dei Pandaren, in onore della Serpe di Giada, ed è la rappresentazione della sua reincarnazione ogni cento anni. Yu'lon ancora dispensa sapienza e intelligenza dal suo tempio nella Foresta di Giada."}
MultiLanguageSpellData['it'][113979] = {name = "Stendardo di Niuzao", additional_info = "2 s di lancio 3\n[q]Un rotolo di canovaccio spesso che, se tenuto in alto, si dispiega per rivelare un orgoglioso emblema dell'Impero dei Pandaren. Pesanti anelli di ferro penzolano dai lunghi nastri di cuoio legati al fondo, tenendo lo stendardo ben teso. Ricamato in ognuna delle strisce di cuoio, leggi un promemoria per il Porta Vessillo: \"Se la paura cerca di indebolirti, tu usala per rivelare il tuo valore\"."}
MultiLanguageSpellData['it'][113980] = {name = "[q3]Ombrello di Chi-Ji", additional_info = "2 s di lancio 3\n[q]La delicata volta di carta di questo ombrello di bambù si è miracolosamente salvata sin dalla sua creazione, ai tempi della lunga dinastia degli Zampa Tonante. La parte inferiore mostra una coltre nera di nubi temporalesche, mentre un imponente sole cremisi adorna la parte superiore. Un breve messaggio compare, scritto con un'elegante calligrafia, tra le nuvole: \"La speranza è come il sole dietro un cielo tempestoso, è sempre nel cuore anche se nascosta\". Chi-Ji, la Gru Rossa, ha continuato a essere un simbolo di speranza per tutti i Pandaren, per secoli. Il tempio a lui dedicato, adornato e imponente, si trova in una giungla inospitale a sud della Valle dei Quattro Venti.\n[q3]Ombrello di Chi-Ji\n[q7]Si vincola alla Brigata\nAccessorio\n+6 Intelletto\n+3 Tempra\n[q2]+ 2 Celerità\n[q2]+ 2 Maestria\n32\n[q]\"I dettagli del Manufatto sono registrati nel tuo Diario di Archeologia, nella scheda dei Manufatti Completati.\""}
MultiLanguageSpellData['it'][113981] = {name = "[q3]Lancia di Xuen", additional_info = "2 s di lancio 3\n[q]Realizzata durante le Guerre dei Troll Zandalari, questa lancia imponente è sorprendentemente leggera e flessibile. L'asta in legno laccato è scavata da profonde cicatrici, anche se la punta appare intatta. A giudicare dalla lunghezza di quest'arma e dalla sua data di origine, si trattava probabilmente di un'arma utilizzata da qualcuno che cavalcava una serpe volante. Incisa sul manico vi è una nota: \"Il tuo unico avversario sei tu\". Xuen, la Tigre Bianca, è leggendario per la sua ferocia e la sua abilità in battaglia. È presso il suo tempio, in alto sulle montagne del Massiccio del Kun-Lai, che i guerrieri temprano la loro forza con la disciplina.\n[q3]Lancia di Xuen\n[q7]Si vincola alla Brigata\nDue mani Arma ad asta\n7 - 15 Danni Velocità 3.60\n(3.1 danni per secondo)\n+4 Agilità\n+6 Tempra\n[q2]+ 4 Critico\n[q2]+ 4 Maestria\nIntegrità 100 / 100\n32\n[q]\"I dettagli del Manufatto sono registrati nel tuo Diario di Archeologia, nella scheda dei Manufatti Completati.\""}
MultiLanguageSpellData['it'][113982] = {name = "Manette della Ribellione", additional_info = "2 s di lancio 3\n[q]Forgiate in ferro e intrise di incantesimi di sottomissione e dolore, queste manette presentano delle punte verso l'interno e sono state usate sulle razze rese schiave dai Mogu. Anche se gli incantesimi sono da tempo svaniti, la loro crudeltà ancora ti dà i brividi."}
MultiLanguageSpellData['it'][113983] = {name = "Pietra Runica Spaccata dei Mogu", additional_info = "2 s di lancio 3\n[q]A differenza delle \"razze inferiori\", che hanno bisogno di istruzione nelle arti della magia, i Mogu ne erano dei veri esperti. Da quanto si è scoperto, i loro incantatori non appartenevano a categorie conosciute, come Maghi o Stregoni, ma ponevano grande enfasi sulle magie che plasmavano la carne o catturavano gli spiriti. Lo strano residuo di magia imbevuto in questa pietra è difficile da capire per le razze moderne di Azeroth. Curiosamente, alcuni dei segni intorno alla runa ricordano la lingua dei Titani."}
MultiLanguageSpellData['it'][113984] = {name = "Braccio di Terracotta", additional_info = "2 s di lancio 3\n[q]Quando i Mogu smisero di rendere schiavi i guerrieri mortali, rivolsero la loro attenzione alla creazione di eserciti di costrutti animati che combattessero al loro posto. Poiché questi guerrieri di terracotta a volte restano dormienti per secoli, è difficile risalire con precisione al momento in cui questo è stato creato o utilizzato. Tuttavia, il taglio alla base del braccio mozzato indica che è caduto in combattimento."}
MultiLanguageSpellData['it'][113985] = {name = "Frusta d'Ossa Pietrificata", additional_info = "2 s di lancio 3\n[q]Questa frusta è stata costruita con la spina dorsale di una creatura grande e antica. Uno strumento di tortura che ha versato il sangue di molti degli schiavi dei Mogu."}
MultiLanguageSpellData['it'][113986] = {name = "Fregio del Re del Tuono", additional_info = "2 s di lancio 3\n[q]Questo emblema di giada reca il simbolo di una corona e di due fulmini incrociati. Un tempo era un distintivo, indossato dai soldati di Lei Shen, primo Imperatore dei Mogu."}
MultiLanguageSpellData['it'][113987] = {name = "Editti del Re del Tuono", additional_info = "2 s di lancio 3\n[q]Questo codice di leggi, scritto nella lingua unica del Primo Impero, è stato accuratamente scolpito su una tavoletta di pietra. In cima alla lista, leggi il primo ordine: la sedizione, l'insurrezione e la ribellione verranno punite con uno sventramento pubblico."}
MultiLanguageSpellData['it'][113988] = {name = "Amuleto di Ferro", additional_info = "2 s di lancio 3\n[q]Questo enorme amuleto pesa tanto quanto un'ascia da battaglia. I guerrieri Mogu spesso indossavano \"gioielli\" come questo a dimostrazione della loro forza."}
MultiLanguageSpellData['it'][113989] = {name = "Ferro per Marchiare del Signore della Guerra", additional_info = "2 s di lancio 3\n[q]Questo ferro rovente per marchiare, decorato con il simbolo di un signore della guerra minore dei Mogu, non era utilizzato sul bestiame, ma su schiavi umani."}
MultiLanguageSpellData['it'][113990] = {name = "Moneta dei Mogu", additional_info = "2 s di lancio 3\n[q]Questa moneta è stata usata durante il regno di Wai, Imperatore dei Mogu, raffigurato con la sua compiaciuta espressione truce. Il rovescio della moneta raffigura il cambio delle dinastie dei Mogu, un processo sanguinoso in cui il regime precedente doveva essere sopraffatto e giustiziato. Da alcuni punti di vista, l'antico Impero dei Mogu era una meritocrazia: tutto si basava sulla forza brutale e sulla perfidia più astuta."}
MultiLanguageSpellData['it'][113991] = {name = "Libro Mastro del Monumento Consumato", additional_info = "2 s di lancio 3\n[q]Pur avendo a disposizione una magia potente, i Mogu spesso preferirono sfruttare degli schiavi per costruire i loro enormi monumenti. Questo libro mastro documenta il costo, in termini di schiavi, della costruzione di uno di questi monumenti."}
MultiLanguageSpellData['it'][113992] = {name = "[q3]Statuetta Quilen", additional_info = "2 s di lancio 3\n[q]Questa statuetta, scolpita durante il breve regno di Hang, Imperatore dei Mogu, faceva parte di un esperimento: legare i servi Quilen a pietre di piccole dimensioni. L'esperimento fu abbandonato perché, così legati, i Quilen vedevano il loro potere grandemente ridotto e dunque perdevano la loro utilità.\n[q3]Statuetta Quilen\n[q7]Si vincola alla Brigata\nUnico equipaggiabileMonile\n[q2]+ 6 Maestria\n[q2]Usa: Evoca il Quilen collegato al manufatto. (10 Min Recupero)\n32\n[q]\"I dettagli del Manufatto sono registrati nel tuo Diario di Archeologia, nella scheda dei Manufatti Completati.\""}
MultiLanguageSpellData['it'][113993] = {name = "[q3]Anatomical Dummy", additional_info = "2 s di lancio 3\n[q]Un manichino anatomico di un Pandaren. Veniva utilizzato per documentare le tecniche di tortura.\n[q3]Manichino Anatomico\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Evoca un Manichino Anatomico sull'area bersaglio per 5 min. Questo sacco da allenamento funziona come un Manichino a Molla.\n\n Utilizzabile solo all'esterno a Pandaria. (1 Ora Recupero)\n[q]\"I dettagli del Manufatto sono registrati nel tuo Diario di Archeologia, nella scheda dei Manufatti Completati.\""}
MultiLanguageSpellData['it'][113994] = {name = "Cosmetic - Loot Sparkles (2.00)", additional_info = nil}
MultiLanguageSpellData['it'][113995] = {name = "CLICCAMI!", additional_info = nil}
MultiLanguageSpellData['it'][113996] = {name = "Armatura d'Ossa", additional_info = "Istantaneo\n[q]Circonda l'incantatore in un'armatura d'ossa, assorbendo un singolo attacco d'ossa."}
