MultiLanguageSpellData['it'][127127] = {name = "Bombasqualo G91", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nViti di Ectoferro (2), Polvere da Sparo Altamente Esplosiva (2)\nIstruttore delle Professioni:\nIngegneria di Pandaria (1)\nCosto:\n10\n\n(3)\n[q2]Usa: Infligge 688 danni da fuoco a un nemico fino a 45 m di distanza e a tutti i nemici entro 10 m dal bersaglio primario. (1 Min Recupero)\n32"}
MultiLanguageSpellData['it'][127128] = {name = "Archibugio del Drago dei Goblin, Modello II", additional_info = "3 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nViti di Ectoferro (3), Polvere da Sparo Altamente Esplosiva (8)\nIstruttore delle Professioni:\nIngegneria di Pandaria (25)\nCosto:\n1\n\n[q2]Usa: Liberi un getto di fulmini, infliggendo 48 danni da natura ai bersagli in un cono frontale di 10 m ogni 0.5 s per 4 s.\n\n È possibile muoversi durante il lancio. (30 S Recupero)\n50 Carici\n32"}
MultiLanguageSpellData['it'][127129] = {name = "[q4]Orotron 4000", additional_info = "2 s di lancio\nStrumenti:\nChiave ad Arco , Martello da Fabbro\nReagenti:\nAcciaio Vivente (4), Lingotto di Trillio (4), Lingotto di Ectoferro (4), Onice Vermiglio (4), Giada Selvaggia (4), Spirito dell'Armonia (4)\nIstruttore delle Professioni:\nIngegneria di Pandaria (75)\nCosto:\n3\n50\n\n[q4]Orotron 4000\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Assembla l'incredibile Orotron 4000, un robot dalla generosità infinita. Orot, come gli piace essere chiamato, fa un regalo casuale a chiunque gli parli, ma solo una volta al giorno. Dura 10 min. (4 Ore Recupero)\nRichiedeIngegneria di Pandaria\n(75)"}
MultiLanguageSpellData['it'][127130] = {name = "[q2]Visori Antinebbia", additional_info = "2 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nViti di Ectoferro (8), Spirito dell'Armonia (2)\nIstruttore delle Professioni:\nIngegneria di Pandaria (1)\nCosto:\n10\n\n[q2]Visori Antinebbia\nSi vincola all'equipaggiamento\nTesta\n[q2]Equipaggia: Ti permette di individuare vene minerarie e cespugli d'erbe aggiuntivi. Funziona solo a Pandaria.\n[q]\"Anche se questi visori sono molto alla moda, non è necessario indossarli per riceverne i benefici.\""}
MultiLanguageSpellData['it'][127131] = {name = "Incudine Termica", additional_info = "2 s di lancio\nStrumenti:\nMartello da Fabbro\nReagenti:\nPolvere da Sparo Altamente Esplosiva (8), Viti di Ectoferro (6)\nIstruttore delle Professioni:\nIngegneria di Pandaria (25)\nCosto:\n1\n\n[q2]Usa: Posiziona un'incudine termica ai tuoi piedi, permettendo a chiunque sia vicino di usarla per forgiare oggetti o fondere metalli. Dura 5 min. (5 Min Recupero)\n20 Carici"}
MultiLanguageSpellData['it'][127132] = {name = "[q3]Generatore di Tunnel Spaziotemporali: Pandaria", additional_info = "2 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nLingotto di Trillio (12), Spirito dell'Armonia (2)\nIstruttore delle Professioni:\nIngegneria di Pandaria (45)\nCosto:\n1\n75\n\n[q3]Generatore di Tunnel Spaziotemporali: Pandaria\nSi vincola all'uso\nGiocattolo\n[q2]Usa: Ti teletrasporta da qualche parte a Pandaria. La posizione esatta è difficile da prevedere, ma sarà comunque piuttosto lontano. (15 Min Recupero)\n29\nRichiedeIngegneria di Pandaria\n(1)\n[q]\"C'è una piccola scritta sul lato: Uoooooooooo!\""}
