MultiLanguageSpellData['it'][127164] = {name = "Serpe delle Nubi Celestiale Dorata", additional_info = "1.5 s di lancio\n[q]Evoca e congeda una Serpe delle Nubi Celestiale Dorata cavalcabile, una cavalcatura volante.\n[q]\"Questa grande creatura irradia calore e speranza, e risplende come l'alba sulle montagne.\"\nMercante:\nTeurgo del Misticismo Ku\nZona:\nIsola Senza Tempo\nFazione:\nImperatore Shaohao - Osannato"}
MultiLanguageSpellData['it'][127165] = {name = "Yu'lei, Figlia della Giada", additional_info = "1.5 s di lancio\n[q]Evoca e congeda Yu'lei, Figlia della Giada, una cavalcatura volante.\n[q]\"Questa grande creatura irradia calore e saggezza, e risplende come i raggi della luna attraverso la giada più pregiata.\"\nMercante:\nTeurga del Misticismo Xia\nZona:\nIsola Senza Tempo\nCosto:\n5000"}
