MultiLanguageSpellData['it'][139771] = {name = "Sferzata Fulminante", additional_info = "Portata illimitata\n2 s di lancio\n[q]Colpisce un nemico con un fulmine che danneggia anche altri bersagli vicini. L'incantesimo colpisce fino a un massimo di 5 bersagli, infliggendo danni da natura maggiori a ogni bersaglio successivo."}
MultiLanguageSpellData['it'][139772] = {name = "Assalto Cosmico", additional_info = "{Canalizzato (1 s di lancio} {) 10 s di recupero}\n[q]Canalizzazione di un Assalto Cosmico."}
MultiLanguageSpellData['it'][139773] = {name = "Stendardo dell'Impero dei Mantid", additional_info = "2 s di lancio\n[q]Pur avendo a disposizione una magia potente, i Mogu spesso preferirono sfruttare degli schiavi per costruire i loro enormi monumenti. Questo libro mastro documenta il costo, in termini di schiavi, della costruzione di uno di questi monumenti."}
MultiLanguageSpellData['it'][139774] = {name = "Assalto Cosmico", additional_info = nil}
MultiLanguageSpellData['it'][139775] = {name = "Stendardo dell'Impero dei Mantid", additional_info = nil}
MultiLanguageSpellData['it'][139776] = {name = "Stendardo dell'Impero dei Mantid", additional_info = "2 s di lancio\n[q]Anche se i Mantid usano la telaria e la seta imperiale, preferiscono un tipo di \"tessuto\" che si ricava dalle ali di diversi tipi di insetti, inclusi loro stessi. Questo stendardo ne è un esempio."}
MultiLanguageSpellData['it'][139777] = {name = "Frantumazione di Pietra", additional_info = "Portata di 25 m\n3 s di lancio\nRichiede Arma da mischia\n[q]Un brutale attacco dall'alto che infligge danni fisici e stordisce tutti i nemici in un cono frontale."}
MultiLanguageSpellData['it'][139778] = {name = "Statue Frozen Slam Prep", additional_info = nil}
MultiLanguageSpellData['it'][139779] = {name = "Antico Distributore di Linfa", additional_info = "2 s di lancio\n[q]I Mantid preferiscono far invecchiare la linfa dei kypari prima di consumarla, e per farlo utilizzano dispositivi come questo. Da questo manufatto antico si intuisce che la forma non è cambiata molto, col passare del tempo."}
MultiLanguageSpellData['it'][139780] = {name = "Mantid Religioso", additional_info = "2 s di lancio\n[q]Questa statua dei Klaxxi'va risale all'arrivo dei Titani. Alla base della statua vi è inscritta una preghiera per la \"creatura dalle sette teste\". La parola \"klaxxi\" significa \"sacerdote\" nella lingua antica."}
MultiLanguageSpellData['it'][139781] = {name = "Faro Sonoro Inerte", additional_info = "2 s di lancio\n[q]La tecnologia alla base dei fari sonori è incomprensibile per tutte le razze che non siano Mantid. Sembra infatti che si adatti solo alla fisiologia dei Mantid. Questo antico segnalatore, anche se intatto, è completamente inerte senza un Mantid a farlo funzionare."}
MultiLanguageSpellData['it'][139782] = {name = "Resti di un Eletto", additional_info = "2 s di lancio\n[q]Apparentemente, il processo di conservazione nell'ambra non è privo di rischi. Dell'Eletto è rimasta solo la testa. Si potrebbe retrodatare alla rivoluzione dei Pandaren, anche se è impossibile stabilire una data certa."}
MultiLanguageSpellData['it'][139783] = {name = "Lampada dei Mantid", additional_info = "2 s di lancio\n[q]Questa lampada non fa luce grazie al fuoco o alla magia. Al suo interno, ci sono molti insetti luminosi conservati nell'ambra."}
MultiLanguageSpellData['it'][139784] = {name = "Collettore di Polline", additional_info = "2 s di lancio\n[q]Difficile capire lo scopo di questo oggetto, ma sembra una specie di collettore di polline."}
MultiLanguageSpellData['it'][139785] = {name = "Contenitore di Linfa dei Kypari", additional_info = "2 s di lancio\n[q]Questo contenitore, anche se di color ambra, è costituito da secrezioni di kunchong. È così anche per molti dei pezzi più comuni dell'arredamento dei Mantid."}
MultiLanguageSpellData['it'][139786] = {name = "[q3]Razziatore dei Cieli dei Mantid", additional_info = "2 s di lancio\n[q]Quest'antica spada \"razziatore dei cieli\" viene usata dai Mantid volanti: estremamente leggera e ben bilanciata, viene fatta dondolare in ampi archi dagli attaccanti che scendono dal cielo avvicinandosi ai nemici. Quasi tutti i Mantid perdono le ali quando diventano abbastanza forti da indossare armature pesanti e armi, è una sorta di rito di passaggio. È molto raro trovare tale maestria in una lama leggera dei Mantid. Probabilmente era utilizzata da un Eletto.\n[q3]Razziatore dei Cieli dei Mantid\n[q7]Si vincola alla Brigata\nUna mano Spada\n4 - 8 Danni Velocità 2.60\n(2.3 danni per secondo)\n+2 Forza\n+3 Tempra\n[q2]+ 2 Celerità\n[q2]+ 2 Maestria\nIntegrità 90 / 90\n32\n[q]\"I dettagli del Manufatto sono registrati nel tuo Diario di Archeologia, nella scheda dei Manufatti Completati.\""}
MultiLanguageSpellData['it'][139787] = {name = "[q3]Generatore d'Impulso Sonico", additional_info = "2 s di lancio\n[q]I Mantid possono generare e ascoltare suoni di uno spettro molto più ampio di quello udibile da altre razze mortali. Proprio l'innata capacità di percepire le frequenze alte e basse ha permesso loro di creare armi come questa. Gli impulsi sonici che emette sono in grado di disfare il tessuto muscolare degli organi a livello cellulare, e un colpo diretto può liquefare le interiora del nemico.\n[q3]Generatore d'Impulso Sonico\n[q7]Si vincola alla Brigata\nA distanza Arma da fuoco\n6 - 12 Danni Velocità 3.00\n(3.0 danni per secondo)\n+4 Agilità\n+6 Tempra\n[q2]+ 4 Celerità\n[q2]+ 4 Maestria\nIntegrità 100 / 100\n32\n[q]\"I dettagli del Manufatto sono registrati nel tuo Diario di Archeologia, nella scheda dei Manufatti Completati.\""}
