MultiLanguageSpellData['it'][145421] = {name = "Veleno Mortale", additional_info = "3 s di lancio\nRichiede Arma da mischia ad una mano\n[q]Impregna le tue armi con un veleno letale che dura 12 s. Ogni colpo ha una probabilità del 30% di avvelenare il nemico, infliggendo 1600 danni da natura in 12 s. Ulteriori accumuli del veleno infliggono istantaneamente 200 danni da natura.\n(Possibilità di Apparire:30%)"}
MultiLanguageSpellData['it'][145422] = {name = "Ventaglio di Lame", additional_info = "35 energia\nIstantaneo\n[q]Lancia una raffica di coltelli a tutti i bersagli entro 10 m, infliggendo 1005 danni fisici. Questo attacco ha una probabilità di applicare i tuoi veleni attivi secondo la loro normale possibilità di applicazione. Fornisce 1005 punti combo se colpisce il tuo attuale bersaglio con punti combo attivi."}
MultiLanguageSpellData['it'][145423] = {name = "Furtività", additional_info = "{Istantaneo} {6 s di recupero}\n[q]Attiva la modalità furtiva, che ti permette di seguire i nemici senza essere visto. Dura fino all'annullamento."}
MultiLanguageSpellData['it'][145424] = {name = "Colpo Basso", additional_info = "{40 energia} {Portata di 10 m}\nIstantaneo\nRichiede Furtività\n[q]Stordisce il bersaglio per 4 s. Richiede la modalità furtiva. Fornisce 2 punto combo."}
MultiLanguageSpellData['it'][145425] = {name = "Passo nell'Ombra", additional_info = "Portata di 100 m\nIstantaneo\n[q]Permette di muoversi nell'ombra e comparire alle spalle del bersaglio, aumentando la velocità di movimento del 70% per 2 s. [ Scaltrezza : Se si conosce già Passo nell'Ombra , le cariche di Passo nell'Ombra aumentano di 1 ]"}
