MultiLanguageSpellData['it'][148266] = {name = "Glifo - Scheletro", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro di Mezzanotte (3)\nProfessione:\nRunografia (75)\nScoperta:\nRicerca: Inchiostro di Mezzanotte\n\nClassi: Cavaliere della Morte\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nRianima Cadavere evoca uno scheletro invece di un Ghoul.\n\n [ Sputafango : Disattivato se è stato scelto il talento Sputafango ] Esclusiva con: Glifo - Geist\n11"}
MultiLanguageSpellData['it'][148270] = {name = "Glifo - Elementale Indomabile", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro di Giadafulgida (3)\nProfessione:\nRunografia (150)\nScoperta:\nRicerca: Inchiostro di Giadafulgida\n\nClassi: Mago\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nIl tuo Elementale dell'Acqua diventa un Elementale dell'Acqua Indomabile. Esclusiva con: Glifo - Evaporazione Glifo - Maree Glifo - Destatempesta Glifo - Profondità Oscure Glifo - Furia Fumante Glifo - Onde Gelide\n11"}
MultiLanguageSpellData['it'][148271] = {name = "Glifo - Evaporazione", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro del Leone (3)\nProfessione:\nRunografia (100)\nScoperta:\nRicerca: Inchiostro del Leone\n\nClassi: Mago\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nRiduce le dimensioni del tuo Elementale dell'Acqua del 15%. Esclusiva con: Glifo - Elementale Indomabile Glifo - Maree Glifo - Destatempesta Glifo - Profondità Oscure Glifo - Furia Fumante Glifo - Onde Gelide\n11"}
MultiLanguageSpellData['it'][148274] = {name = "Glifo - Colonna di Luce", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro dei Sogni (3)\nProfessione:\nRunografia di Pandaria (1)\nScoperta:\nRicerca: Inchiostro dei Sogni\n\nClassi: Paladino\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nLe cure critiche fornite da Folgore Sacra ad altri personaggi fanno apparire una piccola colonna di luce su di loro.\n11"}
MultiLanguageSpellData['it'][148275] = {name = "Glifo - Angeli", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro del Mare (3)\nBottino:\nCreature mondiali\n\nClassi: Sacerdote\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nLanciare incantesimi di cura fornisce una probabilità di ottenere delle ali angeliche. (Possibilità di Apparire:15%)\n11"}
MultiLanguageSpellData['it'][148276] = {name = "Glifo - Spirito Sha", additional_info = "2 s di lancio 2\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro Etereo (3)\nProfessione:\nRunografia delle Terre Esterne (1)\nScoperta:\nRicerca: Inchiostro Etereo\n\n\nClassi: Sacerdote\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nTrasforma il tuo Spirito d'Ombra in uno Spirito Sha. Esclusiva con: Glifo - Prole della Luce Glifo - Genia del Vuoto\n11"}
MultiLanguageSpellData['it'][148278] = {name = "Glifo - Inno Ispirato", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro di Lunafulgida (3)\nProfessione:\nRunografia (25)\nScoperta:\nRicerca: Inchiostro di Lunafulgida\n\nClassi: Sacerdote\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nMentre si canalizza un Inno, appare uno spirito sopra la testa.\n11"}
MultiLanguageSpellData['it'][148281] = {name = "Glifo - Raptor Spirituali", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro del Leone (3)\nProfessione:\nRunografia (100)\nScoperta:\nRicerca: Inchiostro del Leone\n\nClassi: Sciamano\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nI tuoi Lupi Spirituali sono sostituiti da dei Raptor Spirituali.\n11"}
MultiLanguageSpellData['it'][148282] = {name = "Glifo - Presenze Ancestrali", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro di Mezzanotte (3)\nProfessione:\nRunografia (75)\nScoperta:\nRicerca: Inchiostro di Mezzanotte\n\nClassi: Sciamano\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nI bersagli risorti da Spirito Ancestrale sono seguiti per alcuni istanti da antichi fantasmi.\n11"}
MultiLanguageSpellData['it'][148292] = {name = "Glifo - Mastro d'Armi", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro Celestiale (3)\nProfessione:\nRunografia (200)\nScoperta:\nRicerca: Inchiostro Celestiale\n\nClassi: Guerriero\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nL'abilità Avventatezza cambia la forma della tua arma, facendole assumere l'aspetto di un'arma casuale presente nel tuo zaino per 10 min.\n11"}
