MultiLanguageSpellData['it'][156585] = {name = "Olio Falciforme", additional_info = "2 s di lancio\nReagenti:\nFiletto di Pinnamozza Falciforme (3)\nMercante:\nMary Kearie\nOggetto:\nAlchimia di Draenor\nCosto:\n100\nZona:\nCalaluna\n\nMercante:\nKatherine Joplin\nOggetto:\nAlchimia di Draenor\nCosto:\n100\nZona:\nAshran\n\nReagente d'artigianato"}
MultiLanguageSpellData['it'][156586] = {name = "Calderone Alchemico", additional_info = "3.5 s di lancio 1 giorno di recupero\nReagenti:\nEssenza dei Primordiali (3), Minerale di Roccianera (3)\n[q]Genera i reagenti necessari per creare i più potenti agenti alchemici di Draenor. È un'operazione che si può svolgere solo una volta al giorno. Condivide il tempo di recupero con gli altri Calderoni Alchemici."}
MultiLanguageSpellData['it'][156587] = {name = "[q2]Catalizzatore Alchemico", additional_info = "1.5 s di lancio 1 giorno di recupero\nReagenti:\nErba del Gelo (20), Minerale di Roccianera (10)\n[q]Produce 8 Catalizzatori Alchemici. In base alla competenza in Alchimia, può creare catalizzatori aggiuntivi.\n\n È possibile creare anche dell'Iperfuoco e dell'Iperacqua.\n\n Il tempo di recupero si reimposta quotidianamente.\nMercante:\nMary Kearie\nOggetto:\nAlchimia di Draenor\nCosto:\n100\nZona:\nCalaluna\n\nMercante:\nKatherine Joplin\nOggetto:\nAlchimia di Draenor\nCosto:\n100\nZona:\nAshran\n\n[q2]Catalizzatore Alchemico\nReagente d'artigianato\n[q]\"Catalizza delle reazioni che altrimenti richiederebbero migliaia di anni, il che lo rende un ingrediente indispensabile per l'Alchimia di Draenor.\""}
