MultiLanguageSpellData['it'][162000] = {name = "Razziatore di Ferro", additional_info = "Portata illimitata\nIstantaneo\n[q]Carica un bersaglio, infliggendo da 514735 a 568917 danni fisici a chiunque si trovi sulla traiettoria."}
MultiLanguageSpellData['it'][162001] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per costruire un Fortilizio dei Nani nella tua Guarnigione.\n\n Level 1\nRaddoppia le probabilità di ottenere un Potenziamento Bonus raro o epico come ricompensa di missione e ne migliora la qualità. Permette la raccolta di pezzi di armatura dai clan degli Orchi di Draenor da utilizzare per la trasmogrificazione.\n\n Level 2\nPermette di assegnare incarichi di lavoro per la realizzazione di armi e armature dei seguaci in cambio di Risorse per la Guarnigione. Sblocca anche nuovi oggetti per la trasmogrificazione.\n\n Level 3\nFornisce gratuitamente uno dei tre Sigilli del Destino Inevitabile per i tiri bonus in un'incursione una volta alla settimana."}
MultiLanguageSpellData['it'][162002] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare il Fortilizio dei Nani della tua Guarnigione al livello 2.\n\n Level 1\nRaddoppia le probabilità di ottenere un Potenziamento Bonus raro o epico come ricompensa di missione e ne migliora la qualità. Permette la raccolta di pezzi di armatura dai clan degli Orchi di Draenor da utilizzare per la trasmogrificazione.\n\n Level 2\nPermette di assegnare incarichi di lavoro per la realizzazione di armi e armature dei seguaci in cambio di Risorse per la Guarnigione. Sblocca anche nuovi oggetti per la trasmogrificazione.\n\n Level 3\nFornisce gratuitamente uno dei tre Sigilli del Destino Inevitabile per i tiri bonus in un'incursione una volta alla settimana."}
MultiLanguageSpellData['it'][162003] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare il Fortilizio dei Nani della tua Guarnigione al livello 3.\n\n Level 1\nRaddoppia le probabilità di ottenere un Potenziamento Bonus raro o epico come ricompensa di missione e ne migliora la qualità. Permette la raccolta di pezzi di armatura dai clan degli Orchi di Draenor da utilizzare per la trasmogrificazione.\n\n Level 2\nPermette di assegnare incarichi di lavoro per la realizzazione di armi e armature dei seguaci in cambio di Risorse per la Guarnigione. Sblocca anche nuovi oggetti per la trasmogrificazione.\n\n Level 3\nFornisce gratuitamente uno dei tre Sigilli del Destino Inevitabile per i tiri bonus in un'incursione una volta alla settimana."}
