MultiLanguageSpellData['it'][162038] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare il Magazzino della tua Guarnigione al livello 3.\n\n Level 1\nPermette l'accesso alla banca e aumenta di 5 il numero di incarichi di lavoro attivi per tutti gli edifici.\n\n Level 2\nPermette l'accesso alla banca di gilda.\n\n Level 3\nPermette l'accesso alla Banca Eterea e al servizio di trasmogrificazione, e aumenta di 15 il numero di incarichi di lavoro attivi per tutti gli edifici."}
MultiLanguageSpellData['it'][162039] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per costruire un Emporio nella tua Guarnigione.\n\n Level 1\nUn mercante vende ogni giorno beni commerciali. Permette anche di scambiare reagenti con Risorse per la Guarnigione.\n\n Level 2\nPermette l'accesso alla fazione Protettori Sha'tari o a quella degli Orchi Teschio Ridente. Permette anche il recupero su Draenor di parti per la costruzione di una casa d'aste.\n\n Level 3\nAumenta la reputazione ottenuta su Draenor del 20%."}
MultiLanguageSpellData['it'][162040] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare l'Emporio della tua Guarnigione al livello 2.\n\n Level 1\nUn mercante vende ogni giorno beni commerciali. Permette anche di scambiare reagenti con Risorse per la Guarnigione.\n\n Level 2\nPermette l'accesso alla fazione Protettori Sha'tari o a quella degli Orchi Teschio Ridente. Permette anche il recupero su Draenor di parti per la costruzione di una casa d'aste.\n\n Level 3\nAumenta la reputazione ottenuta su Draenor del 20%."}
MultiLanguageSpellData['it'][162041] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare l'Emporio della tua Guarnigione al livello 3.\n\n Level 1\nUn mercante vende ogni giorno beni commerciali. Permette anche di scambiare reagenti con Risorse per la Guarnigione.\n\n Level 2\nPermette l'accesso alla fazione Protettori Sha'tari o a quella degli Orchi Teschio Ridente. Permette anche il recupero su Draenor di parti per la costruzione di una casa d'aste.\n\n Level 3\nAumenta la reputazione ottenuta su Draenor del 20%."}
MultiLanguageSpellData['it'][162042] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare il Serraglio della tua Guarnigione al livello 2.\n\n Level 1\nAttira mascotte élite che puoi sconfiggere per ottenere delle ricompense. Inoltre, permette a 5 delle tue mascotte da combattimento di gironzolare per la Guarnigione.\n\n Level 2\nAumenta la probabilità di intrappolare le mascotte e riduce il tempo di recupero di Resuscita Mascotte su Draenor. Permette a 10 delle tue mascotte di gironzolare per la Guarnigione.\n\n Level 3\nSblocca uno scontro tra mascotte giornaliero che fornisce ricompense uniche."}
MultiLanguageSpellData['it'][162043] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare il Serraglio della tua Guarnigione al livello 3.\n\n Level 1\nAttira mascotte élite che puoi sconfiggere per ottenere delle ricompense. Inoltre, permette a 5 delle tue mascotte da combattimento di gironzolare per la Guarnigione.\n\n Level 2\nAumenta la probabilità di intrappolare le mascotte e riduce il tempo di recupero di Resuscita Mascotte su Draenor. Permette a 10 delle tue mascotte di gironzolare per la Guarnigione.\n\n Level 3\nSblocca uno scontro tra mascotte giornaliero che fornisce ricompense uniche."}
MultiLanguageSpellData['it'][162044] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare gli Scavi di Calaluna della tua Guarnigione al livello 2.\n\n Level 1\nPermette di raccogliere Pietre Draenoriane dalle vene minerarie di Draenor. La Pietra Draenoriana può essere sfruttata per assegnare incarichi di lavoro relativi ai minerali di Draenor.\n\n Level 2\nPermette ai seguaci con la caratteristica Estrazione di lavorare in questo edificio, fornendo un bonus unico. Inoltre, apre una nuova galleria, dando accesso ad altre vene minerarie, e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nUn'altra galleria mineraria fornisce l'accesso a ricche vene minerarie. Inoltre, le guardie della Guarnigione pattugliano la miniera, proteggendola dai Goren ostili. Permette la gestione di 21 incarichi di lavoro alla volta."}
MultiLanguageSpellData['it'][162045] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare gli Scavi di Calaluna della tua Guarnigione al livello 3.\n\n Level 1\nPermette di raccogliere Pietre Draenoriane dalle vene minerarie di Draenor. La Pietra Draenoriana può essere sfruttata per assegnare incarichi di lavoro relativi ai minerali di Draenor.\n\n Level 2\nPermette ai seguaci con la caratteristica Estrazione di lavorare in questo edificio, fornendo un bonus unico. Inoltre, apre una nuova galleria, dando accesso ad altre vene minerarie, e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nUn'altra galleria mineraria fornisce l'accesso a ricche vene minerarie. Inoltre, le guardie della Guarnigione pattugliano la miniera, proteggendola dai Goren ostili. Permette la gestione di 21 incarichi di lavoro alla volta."}
MultiLanguageSpellData['it'][162046] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare il Giardino d'Erbalismo della tua Guarnigione al livello 2.\n\n Level 1\nPermette di piantare una volta al giorno i Semi Draenoriani affinché diventino erbe. Inoltre, diversi tipi di cespugli d'erbe sono disponibili all'interno del Giardino d'Erbalismo.\n\n Level 2\nPermette ai seguaci con la caratteristica Erbalismo di lavorare in questo edificio, fornendo un bonus unico. Aumenta la quantità di erbe che possono essere raccolte nel Giardino d'Erbalismo e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nFa crescere un raro albero da frutta di Draenor nel Giardino d'Erbalismo, che fornisce benefici da cibo. Permette anche la gestione di 21 incarichi di lavoro alla volta."}
MultiLanguageSpellData['it'][162047] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare il Giardino d'Erbalismo della tua Guarnigione al livello 3.\n\n Level 1\nPermette di piantare una volta al giorno i Semi Draenoriani affinché diventino erbe. Inoltre, diversi tipi di cespugli d'erbe sono disponibili all'interno del Giardino d'Erbalismo.\n\n Level 2\nPermette ai seguaci con la caratteristica Erbalismo di lavorare in questo edificio, fornendo un bonus unico. Aumenta la quantità di erbe che possono essere raccolte nel Giardino d'Erbalismo e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nFa crescere un raro albero da frutta di Draenor nel Giardino d'Erbalismo, che fornisce benefici da cibo. Permette anche la gestione di 21 incarichi di lavoro alla volta."}
