MultiLanguageSpellData['it'][162195] = {name = "[q4]Meccavisori Cibernetici", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nParti di Ingranaggio a Molla (100)\nReagenti Facoltativi:\n[] (#50) , Ingranaggio Oliosaldo (#238)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q4]Meccavisori Cibernetici\nSi vincola all'equipaggiamento\nUnico equipaggiabile: Artigianato dei Signori della Guerra (3)Testa Maglia\n8 Armatura\n+5 [Agilità o Intelletto]+7 Tempra\nIntegrità 100 / 100\n[q2]Usa: Permette di vedere molto lontano.\n35\nRichiedeIngegneria di Draenor\n(1)"}
MultiLanguageSpellData['it'][162196] = {name = "[q4]Meccavisori Crepuscolari", additional_info = "2 s di lancio\nStrumenti:\nChiave ad Arco , Microavvitatore Giromatico\nReagenti:\nParti di Ingranaggio a Molla (100)\nReagenti Facoltativi:\n[] (#50) , Ingranaggio Oliosaldo (#238)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q4]Meccavisori Crepuscolari\nSi vincola all'equipaggiamento\nUnico equipaggiabile: Artigianato dei Signori della Guerra (3)Testa Cuoio\n6 Armatura\n+5 [Agilità o Intelletto]+7 Tempra\nIntegrità 100 / 100\n[q2]Usa: Permette di vedere molto lontano.\n35\nRichiedeIngegneria di Draenor\n(1)"}
MultiLanguageSpellData['it'][162197] = {name = "[q4]Meccavisori al Plasma", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nParti di Ingranaggio a Molla (100)\nReagenti Facoltativi:\n[] (#50) , Ingranaggio Oliosaldo (#238)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q4]Meccavisori al Plasma\nSi vincola all'equipaggiamento\nUnico equipaggiabile: Artigianato dei Signori della Guerra (3)Testa Stoffa\n3 Armatura\n+5 Intelletto\n+7 Tempra\nIntegrità 100 / 100\n[q2]Usa: Permette di vedere molto lontano.\n35\nRichiedeIngegneria di Draenor\n(1)"}
MultiLanguageSpellData['it'][162198] = {name = "[q4]Meccavisori Acuminati", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nParti di Ingranaggio a Molla (100)\nReagenti Facoltativi:\n[] (#50) , Ingranaggio Oliosaldo (#238)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q4]Meccavisori Acuminati\nSi vincola all'equipaggiamento\nUnico equipaggiabile: Artigianato dei Signori della Guerra (3)Testa Piastre\n13 Armatura\n+5 [Forza o Intelletto]+7 Tempra\nIntegrità 100 / 100\n[q2]Usa: Permette di vedere molto lontano.\n35\nRichiedeIngegneria di Draenor\n(1)"}
MultiLanguageSpellData['it'][162199] = {name = "[q4]Segatronchi di Straziaferro", additional_info = "3 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nSenza professione:\nRichiede la Bottega d'Ingegneria di livello 3.\nReagenti:\nParti di Ingranaggio a Molla (100)\nReagenti Facoltativi:\n[] (#50) , Grilletto di Puroferro (#239)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q4]Segatronchi di Straziaferro\nSi vincola all'equipaggiamento\nUnico equipaggiabile: Artigianato dei Signori della Guerra (3)A distanza Arma da fuoco\n7 - 13 Danni Velocità 3.00\n(3.3 danni per secondo)\n+5 Agilità\n+7 Tempra\nIntegrità 120 / 120\n35\n[q]\"Per gli ingegneri, un capolavoro. Per i Cacciatori, uno strumento dell'arte di uccidere.\""}
MultiLanguageSpellData['it'][162202] = {name = "[q3]Spaccamissile di Oglethorpe", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nSenza professione:\nRichiede la Bottega d'Ingegneria di livello 2.\nReagenti:\nParti di Ingranaggio a Molla (20)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Spaccamissile di Oglethorpe\n[q2]Usa: Applica in modo permanente un dispositivo speciale a un'arma a distanza, aumentando occasionalmente l'indice di celerità di 115 per 12 s quando si infliggono danni a distanza.\n\n Applicare un dispositivo a un'arma la rende vincolata. Non applicabile a un oggetto di livello superiore a 320.\n35"}
MultiLanguageSpellData['it'][162203] = {name = "[q3]Filamento di Megawatt", additional_info = "2 s di lancio\nStrumenti:\nChiave ad Arco\nSenza professione:\nRichiede la Bottega d'Ingegneria di livello 2.\nReagenti:\nParti di Ingranaggio a Molla (20)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Filamento di Megawatt\n[q2]Usa: Applica in modo permanente un dispositivo elettrificato a un'arma a distanza, aumentando occasionalmente l'indice di critico di 115 per 12 s quando si infliggono danni a distanza.\n\n Applicare un dispositivo a un'arma la rende vincolata. Non applicabile a un oggetto di livello superiore a 320.\n35\n[q]\"Qualsiasi cosa migliora, se è elettrificata.\""}
MultiLanguageSpellData['it'][162204] = {name = "Kit dell'Aliante dei Goblin", additional_info = "2 s di lancio\nStrumenti:\nChiave ad Arco\nReagenti:\nMinerale di Puroferro (8), Pelliccia Splendida (5)\nMercante:\nZaren Hoffle\nOggetto:\nIngegneria di Draenor\nCosto:\n100\nZona:\nCalaluna\n\nMercante:\nSean Chiavedritta\nOggetto:\nIngegneria di Draenor\nCosto:\n100\nZona:\nAshran\n\n(5)\n[q2]Usa: Riduce la velocità di caduta per 2 min. (3 Min Recupero)"}
MultiLanguageSpellData['it'][162205] = {name = "[q3]Depredatore di Findle", additional_info = "2 s di lancio\nStrumenti:\nMartello da Fabbro\nSenza professione:\nRichiede la Bottega d'Ingegneria di livello 2.\nReagenti:\nParti di Ingranaggio a Molla (50)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Depredatore di Findle\nSi vincola all'uso\nGiocattolo\n[q2]Usa: Recuperi il bottino da un cadavere vicino. Utilizzabile solo su Draenor. (3 S Recupero)"}
MultiLanguageSpellData['it'][162206] = {name = "[q3]Restringimondo", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nParti di Ingranaggio a Molla (50)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Restringimondo\nGiocattolo\n[q2]Usa: Riesci a rimpicciolire il mondo per 5 min o finché non entri in combattimento. (15 Min Recupero)\nRichiedeIngegneria di Draenor\n(1)\n[q]\"Un uso eccessivo può portare a un restringimento permanente.\""}
MultiLanguageSpellData['it'][162207] = {name = "NasconDinamo 54", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nMinerale di Roccianera (2), Minerale di Puroferro (2), Fogliaspina di Nagrand (2)\nMercante:\nZaren Hoffle\nOggetto:\nIngegneria di Draenor\nCosto:\n100\nZona:\nCalaluna\n\nMercante:\nSean Chiavedritta\nOggetto:\nIngegneria di Draenor\nCosto:\n100\nZona:\nAshran\n\n(5)\n[q2]Usa: Nasconde l'utilizzatore in un campo d'occultamento finché rimane immobile. Non utilizzabile in combattimento. Lo scudo persiste per massimo 6 s dopo che ci si è mossi.\n NasconDinamo condivide il tempo di recupero con le pozioni non di cura. Inefficace oltre il livello 49. (5 Min Recupero)\n35\n[q]\"L'invisibilità è per gli scarsi!\""}
MultiLanguageSpellData['it'][162208] = {name = "[q2]Coltellino Multiuso Definitivo degli Gnomi", additional_info = "2 s di lancio\nReagenti:\nParti di Ingranaggio a Molla (5)\n[q2]Coltellino Multiuso Definitivo degli Gnomi\n[q2]Aumenta la competenza in Estrazione di Draenor di 10.\n Aumenta la competenza in Erbalismo di Draenor di 10.\n Aumenta la competenza in Scuoiatura di Draenor di 10.\n[q]\"Include tutti gli strumenti per le professioni.\""}
MultiLanguageSpellData['it'][162209] = {name = "[q3]Fendibecco Meccanico", additional_info = "3.5 s di lancio\nStrumenti:\nChiave ad Arco\nSenza professione:\nRichiede la Bottega d'Ingegneria di livello 3.\nReagenti:\nParti di Ingranaggio a Molla (50)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Fendibecco Meccanico\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Evoca e congeda un Fendibecco Meccanico.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageSpellData['it'][162210] = {name = "[q3]Cinghiale del Gelo Meccanico", additional_info = "3.5 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nSenza professione:\nRichiede la Bottega d'Ingegneria di livello 3.\nReagenti:\nParti di Ingranaggio a Molla (50), Pelliccia Splendida (40)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Cinghiale del Gelo Meccanico\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare un Cinghiale del Gelo Meccanico.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageSpellData['it'][162214] = {name = "[q3]Ologramma Personale", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nSenza professione:\nRichiede la Bottega d'Ingegneria di livello 3.\nReagenti:\nParti di Ingranaggio a Molla (50)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Ologramma Personale\nSi vincola all'uso\nGiocattolo\n[q2]Usa: Crei un ologramma temporaneo di te stesso per 1 min. (5 Min Recupero)\n[q]\"L'immagine potrebbe rispondere ad alcune emote.\""}
MultiLanguageSpellData['it'][162216] = {name = "[q3]Centrifuga del Tunnel Spaziotemporale", additional_info = "2 s di lancio\nStrumenti:\nMartello da Fabbro , Chiave ad Arco\nReagenti:\nParti di Ingranaggio a Molla (50)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Centrifuga del Tunnel Spaziotemporale\nSi vincola all'uso\nGiocattolo\n[q2]Usa: Crea un tunnel spaziotemporale che l'ingegnere può usare per spostarsi su Draenor. (4 Ore Recupero)\n34\nRichiedeIngegneria di Draenor\n(1)"}
MultiLanguageSpellData['it'][162217] = {name = "[q3]Fulminatore a Scambio", additional_info = "2 s di lancio\nStrumenti:\nChiave ad Arco\nSenza professione:\nRichiede la Bottega d'Ingegneria di livello 3.\nReagenti:\nParti di Ingranaggio a Molla (50), Cristallo Temporale\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Fulminatore a Scambio\nSi vincola all'uso\n[q2]Usa: Scambia la tua posizione con quella di un altro membro del gruppo. Non utilizzabile in combattimento. (1 Min Recupero)\n[q]\"Attenzione: fulminare qualcuno che usa un Silenziatore Neurale potrebbe essere molto pericoloso.\""}
MultiLanguageSpellData['it'][162218] = {name = "[q4]Orotron 5000", additional_info = "2 s di lancio\nStrumenti:\nMartello da Fabbro , Microavvitatore Giromatico\nReagenti:\nParti di Ingranaggio a Molla (100)\nMercante:\nNik Accianelli\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q4]Orotron 5000\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Assembla l'Orotron 5000 potenziato, un robot crudele eppure generoso. Continuerà a fare regali quotidiani ai personaggi, ma combatterà anche gli altri Orotron... fino alla morte. (4 Ore Recupero)\nRichiedeIngegneria di Draenor\n(1)"}
